import { readFileSync } from 'node:fs';
import { ok, fail } from './result.js';

const PRODUCTS = JSON.parse(readFileSync(new URL('../data/catalogue.json', import.meta.url), 'utf8'));

/**
 * All products: { sku, name, unitPrice (cents, without VAT), vatRate (percent) }.
 * @returns {Array<{ sku: string, name: string, unitPrice: number, vatRate: number }>}
 */
export function listProducts() {
  return PRODUCTS.map((p) => ({ ...p }));
}

/**
 * One product by SKU.
 * @param {string} sku
 */
export function getProduct(sku) {
  const p = PRODUCTS.find((x) => x.sku === sku);
  return p ? ok({ ...p }) : fail('UNKNOWN_SKU');
}
</file>

<file path="src/customers.js">
import { readFileSync } from 'node:fs';
import { ok, fail } from './result.js';

const CUSTOMERS = JSON.parse(readFileSync(new URL('../data/customers.json', import.meta.url), 'utf8'));

/**
 * Discount percentages by customer tier.
 * @type {{ gold: number, silver: number, standard: number }}
 */
export const TIER_DISCOUNTS = {
  gold: 5,
  silver: 2.5,
  standard: 0,
};

/**
 * Normalize a customer ID: trim whitespace and convert to uppercase.
 * @param {string} id
 * @returns {string}
 */
export function normalizeId(id) {
  return String(id).trim().toUpperCase();
}

/**
 * All customers: { id, name, email, country, tier }.
 */
export function listCustomers() {
  return CUSTOMERS.map((c) => ({ ...c }));
}

/**
 * One customer by id (normalized).
 * @param {string} id
 */
export function getCustomer(id) {
  const normalizedId = normalizeId(id);
  const c = CUSTOMERS.find((x) => x.id === normalizedId);
  return c ? ok({ ...c }) : fail('CUSTOMER_NOT_FOUND');
}

/**
 * Check a customer record before it is stored.
 * @param {{ id?: string, name?: string, email?: string }} c
 */
export function validateCustomer(c) {
  if (!c || !c.id || !c.name || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(c.email ?? '')) return fail('CUSTOMER_INVALID');
  return ok({ ...c });
}
</file>

<file path="src/dates.js">
/**
 * Check if a string is a valid date in YYYY-MM-DD format.
 * @param {string} dateStr
 * @returns {boolean}
 */
export function isValidDate(dateStr) {
  // Check format YYYY-MM-DD
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return false;

  // Parse and validate in UTC
  const date = new Date(dateStr + 'T00:00:00Z');
  const [year, month, day] = dateStr.split('-').map(Number);

  return date.getUTCFullYear() === year &&
         date.getUTCMonth() + 1 === month &&
         date.getUTCDate() === day;
}

/**
 * Add n days to a date string (YYYY-MM-DD), returning a new date string.
 * All operations are done in UTC.
 * @param {string} date - Date string in YYYY-MM-DD format
 * @param {number} n - Number of days to add (can be negative)
 * @returns {string} New date string in YYYY-MM-DD format
 */
export function addDays(date, n) {
  const d = new Date(date + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);

  const year = d.getUTCFullYear();
  const month = String(d.getUTCMonth() + 1).padStart(2, '0');
  const day = String(d.getUTCDate()).padStart(2, '0');

  return `${year}-${month}-${day}`;
}

/**
 * Calculate the number of days between two dates (b - a), in whole days.
 * All operations are done in UTC.
 * @param {string} a - Start date string in YYYY-MM-DD format
 * @param {string} b - End date string in YYYY-MM-DD format
 * @returns {number} Number of whole days (b - a)
 */
export function daysBetween(a, b) {
  const dateA = new Date(a + 'T00:00:00Z');
  const dateB = new Date(b + 'T00:00:00Z');

  const diffMs = dateB - dateA;
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}
</file>

